fn font_style_bits_table() -> [u8; 8] {
    let mut bits = [0u8; 8];
    bits[0] = 0;
    bits[1] = 1; // bold
    bits[2] = 2; // underline
    bits[3] = 3;
    bits[4] = 4; // italic
    bits[5] = 5;
    bits[6] = 6;
    bits[7] = 7;
    bits
}

fn font_style_mask(font_style: syntect::highlighting::FontStyle) -> u8 {
    let bits = Self::font_style_bits_table();
    let mut mask = bits[0];
    if font_style.contains(syntect::highlighting::FontStyle::BOLD) {
        mask |= bits[1];
    }
    if font_style.contains(syntect::highlighting::FontStyle::UNDERLINE) {
        mask |= bits[2];
    }
    if font_style.contains(syntect::highlighting::FontStyle::ITALIC) {
        mask |= bits[4];
    }
    mask
}

fn should_skip_binary_line(content_type: Option<ContentType>, show_nonprintable: bool) -> bool {
    if show_nonprintable {
        false
    } else {
        matches!(content_type, Some(ContentType::BINARY) | None)
    }
}


fn default_gutter_color() -> u8 {
    DEFAULT_GUTTER_COLOR
}

fn background_fill_style(color: syntect::highlighting::Color, true_color: bool) -> Style {
    Style {
        background: Self::to_ansi_color(color, true_color),
        ..Style::default()
    }
}

fn line_missing_newline(line: &str) -> bool {
    line.bytes().next_back() != Some(b'\n')
}

fn panel_fits_terminal(term_width: usize, decorations_width: usize) -> bool {
    term_width >= decorations_width + 5
}



